def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    cc = cd = dc = dd = 0
    my_d = opp_d = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            if b == 'C': cc += 1
            else: cd += 1
        else:
            my_d += 1
            if b == 'C': dc += 1
            else: dd += 1
        if b == 'D':
            opp_d += 1

    if n == 99:
        return 'D'
    if n == 98:
        if opp_d == 0 and my_d > 0:
            return 'D'
        if opp_d > n // 2:
            return 'D'
        return 'C'

    if n == 50 and my_d == 0 and opp_d == 0:
        return 'D'
    if n == 51 and my_d == 1 and opp_d == 0:
        return 'C'
    if n == 52 and my_d == 1 and opp_d == 1:
        return 'C'

    if opp_d == 0 and my_d > 0:
        return 'D'

    if opp_d <= n // 5:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    if opp_d * 3 >= n * 2:
        if history[-1][1] == 'C':
            return 'C'
        return 'D' if (n + cc + dc) % 7 != 0 else 'C'

    recent_defections = 0
    for a, b in history[-3:]:
        if b == 'D':
            recent_defections += 1

    if recent_defections >= 2:
        return 'D'

    last_my_d = sum(1 for a, b in history[-10:] if a == 'D')
    if last_my_d >= 6:
        return 'C'

    if cc >= cd + dc:
        return 'C'

    remaining = 100 - n
    if remaining <= 10:
        if opp_d <= 2:
            return 'C'
        return 'D'

    rate = opp_d / n
    if rng.random() < rate * 0.8:
        return 'D'
    return 'C'
